def fusionar(intervalos):
    if not intervals:
        return []

    # Ordenar los intervalos por inicio
    intervals = sorted(intervals, key=lambda x: x[0])

    resultado = [intervalos[0]]

    for inicio, fin in intervalos[1:]:
        if resultado and resultado[-1][1] >= inicio:
            # Si el último intervalo se toca o toca en el mismo punto, fusionar
            resultado[-1] = (resultado[-1][0], max(resultado[-1][1], fin))
        else:
            resultado.append((inicio, fin))

    return resultado

