def formatear_bytes(n):
    if n < 0:
        return "Error: El número de bytes no puede ser negativo"

    unidades = [
        ("B", 1),
        ("KB", 1024),
        ("MB", 1024**2),
        ("GB", 1024**3)
    ]

    for nombre, factor in unidades:
        if n >= factor:
            valor = n / factor
            if nombre == "B":
                return f"{valor:.1f} B"
            else:
                return f"{valor:.1f} {nombre}"

    return f"{n:.1f} B"

